SELECT CASE WHEN discount >= 0.37 THEN 'HIGH' ELSE 'LOW' END AS discount_tier, DATE_TRUNC('YEAR', order_date) AS year_start, status, COUNT(DISTINCT customer_id) AS distinct_customer_ids, COUNT(CASE WHEN status = 'RETURNED' THEN 1 END) AS returned_count FROM orders GROUP BY CUBE (CASE WHEN discount >= 0.37 THEN 'HIGH' ELSE 'LOW' END, DATE_TRUNC('YEAR', order_date), status) ORDER BY distinct_customer_ids DESC NULLS FIRST;
